-- A1-Basic and A1-Youth (Admin -> Products): the two screens the right way
-- round, the Basic's own page, and a switch between the two (2026-10-15).
--
-- The owner checked the real machines: the Basic has the colour screen with
-- Wi-Fi, the Youth has the plain status panel (Full, Lack, Blocking, battery
-- level) and no Wi-Fi. The model list we had was the wrong way round, so the
-- live Youth page claimed Wi-Fi, 4G and three modes.
--
--   A1-Youth  description, figures, the handle section ("Status at a glance."
--             with its own panel photo) and the spec table now say: status
--             screen, no Wi-Fi, one operating mode. Photos are unchanged.
--   A1-Basic  gets the full-screen page: the same sections as the Youth (the
--             two differ only in the screen), its own photos (the rear view
--             with the lit colour screen as the header and card, the owner's
--             screen photo for "Check the reports."), Wi-Fi & 4G, reports,
--             three modes. It stays hidden: tick Visible in Admin afterwards.
--   Both      list each other under "Other models", so each page's header
--             shows an "A1-Basic | A1-Youth" switch once both are on show.
--
-- One mode / three modes and 4G follow the corrected model list; the screens
-- agree (the Basic's has mode arrows and a mobile-signal icon).
--
-- Needs the site code with the model switch (Admin "Other models") live
-- first; before that, the switch just doesn't show. The Basic's photos are on
-- S3 (findmyrobo-media, Aventurier/A1-Basic/A1-Basic-*.webp).
--
-- Replaces both pages whole (built from the live Youth page of 2026-10-15),
-- so run it before editing either page in Admin. Safe to re-run.
--
-- Run in Supabase: SQL Editor -> New query -> paste -> Run. Nothing to edit.

begin;

update public.products
set tagline = $j${"en":"A walk-behind floor scrubber with a simple status screen and one operating mode.","th":"เครื่องขัดพื้นแบบเดินตาม หน้าจอแสดงสถานะแบบเรียบง่าย มีโหมดการทำงาน 1 โหมด"}$j$::jsonb,
    description = $j${"en":"Brand-new Aventurier A1-Youth walk-behind floor scrubber in Thailand: status screen, one operating mode, 800–1,200 m²/h, one battery included. Get a quote from FindMyRobo.","th":"เครื่องขัดพื้นแบบเดินตาม Aventurier A1-Youth (เครื่องใหม่) ในประเทศไทย หน้าจอแสดงสถานะ โหมดการทำงาน 1 โหมด ทำความสะอาด 800–1,200 ตร.ม./ชม. ให้แบตเตอรี่มา 1 ก้อน ขอใบเสนอราคาจาก FindMyRobo"}$j$::jsonb,
    page = $j${"blocks":[{"body":{"en":"The handle screen warns when the tank is full, the water is low or something is blocking, and shows the level of each battery. Youth has no Wi-Fi: for cleaning reports over Wi-Fi and 4G, see the A1-Basic.","th":"หน้าจอบนด้ามจับแจ้งเตือนถังเต็ม น้ำไม่พอ และสิ่งกีดขวาง พร้อมแสดงระดับแบตเตอรี่แต่ละก้อน รุ่น Youth ไม่มี Wi-Fi หากต้องการตรวจรายงานการทำความสะอาดผ่าน Wi-Fi และ 4G ดูรุ่น A1-Basic"},"type":"feature","image":"/models/aventurier/youth/handle.webp","eyebrow":{"en":"Handle screen","th":"หน้าจอบนด้ามจับ"},"heading":{"en":"Status at a glance.","th":"ดูสถานะได้ทันที"}},{"body":{"en":"Two disc brushes scrub the floor. The Artist 1 brochure rates suction at 8,000 Pa, brush pressure at 15 kg and brush speed at 350 RPM, and says the floor is dry straight after cleaning.","th":"แปรงจาน 2 หัวขัดพื้น เอกสาร Artist 1 ระบุแรงดูด 8,000 Pa แรงกดแปรง 15 กก. ความเร็วแปรง 350 รอบต่อนาที และพื้นแห้งทันทีหลังทำความสะอาด"},"type":"feature","image":"/models/aventurier/brushes.webp","eyebrow":{"en":"Cleaning","th":"การทำความสะอาด"},"heading":{"en":"Scrub, then dry.","th":"ขัด แล้วพื้นแห้งทันที"}},{"body":{"en":"One battery is included. The base has a second bay, and extra batteries are sold separately. On the included battery the brochure lists 75 minutes in ECO mode.","th":"ให้แบตเตอรี่มา 1 ก้อน ฐานเครื่องมีช่องสำหรับก้อนที่สอง และมีแบตเตอรี่ขายแยก เอกสารระบุระยะเวลาทำงาน 75 นาทีในโหมด ECO เมื่อใช้แบตเตอรี่ก้อนเดียว"},"type":"feature","image":"/models/aventurier/youth/batteries.webp","eyebrow":{"en":"Battery","th":"แบตเตอรี่"},"heading":{"en":"One battery to start.","th":"เริ่มต้นด้วยแบตเตอรี่ 1 ก้อน"}}],"showcase":{"colors":[{"image":"/models/aventurier/youth/a1-grey.webp","label":{"en":"Grey","th":"สีเทา"},"swatch":"#85909c"},{"image":"/models/aventurier/youth/hero-white.webp","label":{"en":"White","th":"สีขาว"},"swatch":"#f3f3f3"}],"eyebrow":{"en":"Aventurier · Walk-behind floor scrubber","th":"Aventurier · เครื่องขัดพื้นแบบเดินตาม"},"figures":[{"label":{"en":"Cleaning rate","th":"อัตราการทำความสะอาด"},"value":"800–1,200 m²/h"},{"value":"1","label":{"en":"Operating mode","th":"โหมดการทำงาน"}},{"label":{"en":"Runtime, one battery","th":"ระยะเวลาทำงาน แบตเตอรี่ 1 ก้อน"},"value":"75 min"},{"value":"40 cm","label":{"en":"Working width","th":"ความกว้างในการทำงาน"}}],"heroImage":"/models/aventurier/youth/hero.webp","models":["aventurier-a1-basic"]},"specGroups":[{"rows":[{"label":{"en":"Cleaning rate","th":"อัตราการทำความสะอาด"},"value":{"en":"800–1,200 m²/h","th":"800–1,200 m²/h"}},{"label":{"en":"Working width","th":"ความกว้างในการทำงาน"},"value":{"en":"40 cm","th":"40 ซม."}},{"label":{"en":"Suction","th":"แรงดูด"},"value":{"en":"8,000 Pa","th":"8,000 Pa"}},{"label":{"en":"Brush pressure","th":"แรงกดแปรง"},"value":{"en":"15 kg","th":"15 กก."}},{"label":{"en":"Brush speed","th":"ความเร็วแปรง"},"value":{"en":"350 RPM","th":"350 รอบต่อนาที"}},{"label":{"en":"Noise","th":"เสียง"},"value":{"en":"60 dB(A)","th":"60 dB(A)"}},{"label":{"en":"Operating modes","th":"โหมดการทำงาน"},"value":{"en":"1","th":"1 โหมด"}},{"label":{"en":"Floors","th":"พื้นผิวที่ใช้ได้"},"value":{"en":"Tile, granite, marble, PVC, epoxy, cement","th":"กระเบื้อง หินแกรนิต หินอ่อน พีวีซี อีพ็อกซี ปูน"}}],"title":{"en":"Cleaning","th":"การทำความสะอาด"}},{"rows":[{"label":{"en":"Solution tank","th":"ถังน้ำยา"},"value":{"en":"4 L","th":"4 ลิตร"}},{"label":{"en":"Recovery tank","th":"ถังน้ำเสีย"},"value":{"en":"4 L","th":"4 ลิตร"}}],"title":{"en":"Water","th":"น้ำ"}},{"rows":[{"label":{"en":"Included","th":"ที่ให้มา"},"value":{"en":"1 battery. Extra batteries sold separately","th":"1 ก้อน แบตเตอรี่เพิ่มมีขายแยก"}},{"label":{"en":"Runtime","th":"ระยะเวลาทำงาน"},"value":{"en":"75 min, one battery, ECO mode","th":"75 นาที แบตเตอรี่ 1 ก้อน โหมด ECO"}}],"title":{"en":"Battery","th":"แบตเตอรี่"}},{"rows":[{"label":{"en":"Wi-Fi / 4G","th":"Wi-Fi / 4G"},"value":{"en":"No","th":"ไม่มี"}},{"label":{"en":"Handle screen","th":"หน้าจอบนด้ามจับ"},"value":{"en":"Full, Lack, Blocking, battery level","th":"ถังเต็ม น้ำไม่พอ สิ่งกีดขวาง ระดับแบตเตอรี่"}}],"title":{"en":"Connectivity","th":"การเชื่อมต่อ"}},{"rows":[{"label":{"en":"Dimensions","th":"ขนาด"},"value":{"en":"1,104 × 439 × 346 mm","th":"1,104 × 439 × 346 มม."}},{"label":{"en":"Weight","th":"น้ำหนัก"},"value":{"en":"22 kg","th":"22 กก."}}],"title":{"en":"Size and weight","th":"ขนาดและน้ำหนัก"}}]}$j$::jsonb
where id = 'aventurier-a1-youth';

update public.products
set tagline = $j${"en":"A walk-behind floor scrubber with a colour screen, Wi-Fi and 4G, so cleaning reports can be checked. Three operating modes.","th":"เครื่องขัดพื้นแบบเดินตาม หน้าจอสี เชื่อมต่อ Wi-Fi และ 4G เพื่อตรวจรายงานการทำความสะอาด มีโหมดการทำงาน 3 โหมด"}$j$::jsonb,
    description = $j${"en":"Brand-new Aventurier A1-Basic walk-behind floor scrubber in Thailand: colour screen, Wi-Fi and 4G, 3 operating modes, 800–1,200 m²/h, one battery included. Get a quote from FindMyRobo.","th":"เครื่องขัดพื้นแบบเดินตาม Aventurier A1-Basic (เครื่องใหม่) ในประเทศไทย หน้าจอสี เชื่อมต่อ Wi-Fi และ 4G โหมดการทำงาน 3 โหมด ทำความสะอาด 800–1,200 ตร.ม./ชม. ให้แบตเตอรี่มา 1 ก้อน ขอใบเสนอราคาจาก FindMyRobo"}$j$::jsonb,
    image_url = 'https://d5hk9n8my7l32.cloudfront.net/Aventurier/A1-Basic/A1-Basic-card.webp',
    page = $j${"blocks":[{"body":{"en":"Basic connects over Wi-Fi and 4G, so cleaning reports can be checked. Its colour screen shows the charge of each battery and the cleaning mode, and the arrows switch between modes.","th":"รุ่น Basic เชื่อมต่อผ่าน Wi-Fi และ 4G จึงตรวจรายงานการทำความสะอาดได้ หน้าจอสีแสดงระดับแบตเตอรี่แต่ละก้อนและโหมดการทำความสะอาด กดลูกศรเพื่อเปลี่ยนโหมด"},"type":"feature","image":"https://d5hk9n8my7l32.cloudfront.net/Aventurier/A1-Basic/A1-Basic-screen.webp","eyebrow":{"en":"Wi-Fi and 4G","th":"Wi-Fi และ 4G"},"heading":{"en":"Check the reports.","th":"ตรวจรายงานได้"}},{"body":{"en":"Two disc brushes scrub the floor. The Artist 1 brochure rates suction at 8,000 Pa, brush pressure at 15 kg and brush speed at 350 RPM, and says the floor is dry straight after cleaning.","th":"แปรงจาน 2 หัวขัดพื้น เอกสาร Artist 1 ระบุแรงดูด 8,000 Pa แรงกดแปรง 15 กก. ความเร็วแปรง 350 รอบต่อนาที และพื้นแห้งทันทีหลังทำความสะอาด"},"type":"feature","image":"/models/aventurier/brushes.webp","eyebrow":{"en":"Cleaning","th":"การทำความสะอาด"},"heading":{"en":"Scrub, then dry.","th":"ขัด แล้วพื้นแห้งทันที"}},{"body":{"en":"One battery is included. The base has a second bay, and extra batteries are sold separately. On the included battery the brochure lists 75 minutes in ECO mode.","th":"ให้แบตเตอรี่มา 1 ก้อน ฐานเครื่องมีช่องสำหรับก้อนที่สอง และมีแบตเตอรี่ขายแยก เอกสารระบุระยะเวลาทำงาน 75 นาทีในโหมด ECO เมื่อใช้แบตเตอรี่ก้อนเดียว"},"type":"feature","image":"/models/aventurier/youth/batteries.webp","eyebrow":{"en":"Battery","th":"แบตเตอรี่"},"heading":{"en":"One battery to start.","th":"เริ่มต้นด้วยแบตเตอรี่ 1 ก้อน"}}],"showcase":{"eyebrow":{"en":"Aventurier · Walk-behind floor scrubber","th":"Aventurier · เครื่องขัดพื้นแบบเดินตาม"},"figures":[{"label":{"en":"Cleaning rate","th":"อัตราการทำความสะอาด"},"value":"800–1,200 m²/h"},{"label":{"en":"Operating modes","th":"โหมดการทำงาน"},"value":"3"},{"label":{"en":"Runtime, one battery","th":"ระยะเวลาทำงาน แบตเตอรี่ 1 ก้อน"},"value":"75 min"},{"label":{"en":"Connectivity","th":"การเชื่อมต่อ"},"value":"Wi-Fi & 4G"}],"heroImage":"https://d5hk9n8my7l32.cloudfront.net/Aventurier/A1-Basic/A1-Basic-hero.webp","models":["aventurier-a1-youth"]},"specGroups":[{"rows":[{"label":{"en":"Cleaning rate","th":"อัตราการทำความสะอาด"},"value":{"en":"800–1,200 m²/h","th":"800–1,200 m²/h"}},{"label":{"en":"Working width","th":"ความกว้างในการทำงาน"},"value":{"en":"40 cm","th":"40 ซม."}},{"label":{"en":"Suction","th":"แรงดูด"},"value":{"en":"8,000 Pa","th":"8,000 Pa"}},{"label":{"en":"Brush pressure","th":"แรงกดแปรง"},"value":{"en":"15 kg","th":"15 กก."}},{"label":{"en":"Brush speed","th":"ความเร็วแปรง"},"value":{"en":"350 RPM","th":"350 รอบต่อนาที"}},{"label":{"en":"Noise","th":"เสียง"},"value":{"en":"60 dB(A)","th":"60 dB(A)"}},{"label":{"en":"Operating modes","th":"โหมดการทำงาน"},"value":{"en":"3","th":"3 โหมด"}},{"label":{"en":"Floors","th":"พื้นผิวที่ใช้ได้"},"value":{"en":"Tile, granite, marble, PVC, epoxy, cement","th":"กระเบื้อง หินแกรนิต หินอ่อน พีวีซี อีพ็อกซี ปูน"}}],"title":{"en":"Cleaning","th":"การทำความสะอาด"}},{"rows":[{"label":{"en":"Solution tank","th":"ถังน้ำยา"},"value":{"en":"4 L","th":"4 ลิตร"}},{"label":{"en":"Recovery tank","th":"ถังน้ำเสีย"},"value":{"en":"4 L","th":"4 ลิตร"}}],"title":{"en":"Water","th":"น้ำ"}},{"rows":[{"label":{"en":"Included","th":"ที่ให้มา"},"value":{"en":"1 battery. Extra batteries sold separately","th":"1 ก้อน แบตเตอรี่เพิ่มมีขายแยก"}},{"label":{"en":"Runtime","th":"ระยะเวลาทำงาน"},"value":{"en":"75 min, one battery, ECO mode","th":"75 นาที แบตเตอรี่ 1 ก้อน โหมด ECO"}}],"title":{"en":"Battery","th":"แบตเตอรี่"}},{"rows":[{"label":{"en":"Connection","th":"การเชื่อมต่อ"},"value":{"en":"Wi-Fi & 4G","th":"Wi-Fi & 4G"}},{"label":{"en":"Reports","th":"รายงาน"},"value":{"en":"Can be checked","th":"ตรวจสอบได้"}},{"label":{"en":"Handle screen","th":"หน้าจอบนด้ามจับ"},"value":{"en":"Colour screen: battery levels, mode","th":"จอสี แสดงระดับแบตเตอรี่และโหมด"}}],"title":{"en":"Connectivity","th":"การเชื่อมต่อ"}},{"rows":[{"label":{"en":"Dimensions","th":"ขนาด"},"value":{"en":"1,104 × 439 × 346 mm","th":"1,104 × 439 × 346 มม."}},{"label":{"en":"Weight","th":"น้ำหนัก"},"value":{"en":"22 kg","th":"22 กก."}}],"title":{"en":"Size and weight","th":"ขนาดและน้ำหนัก"}}]}$j$::jsonb
